insert into public.yachts (sort, slug, model, year, length_m, beam_m, draft_m, cabins, berths, heads, engine_hp, base, used_for, charter_from_eur, photo_id, photo_alt, description) values
  (6, 'beneteau-oceanis-34-1', 'Beneteau Oceanis 34.1', 2023, 10.6, 3.5, 2.0, 3, 6, 1, 21, 'Fethiye, Türkiye', 'Introduction to Yachting', 2000, '/fleet/beneteau-oceanis-34-1.webp', 'A Beneteau Oceanis 34.1 sailing on blue water', 'A small, light boat that answers every touch of the helm. Three cabins and one head suit a beginner crew of four with an instructor, and every sail control is easy to see and reach.'),
  (7, 'beneteau-oceanis-38-1', 'Beneteau Oceanis 38.1', 2023, 11.5, 4.0, 2.2, 3, 6, 2, 30, 'Fethiye, Türkiye', 'Flotilla Skipper courses', 1800, '/fleet/beneteau-oceanis-38-1.webp', 'A Beneteau Oceanis 38.1 under sail off the coast', 'Easy to handle with a small crew, with twin wheels and a clear deck. Our usual boat for first skippers on the Flotilla course.'),
  (8, 'bavaria-c38', 'Bavaria C38', 2024, 11.4, 4.0, 2.0, 3, 6, 2, 30, 'Fethiye, Türkiye', 'Bareboat Skipper courses', 1890, '/fleet/bavaria-c38.webp', 'A Bavaria C38 sailing in a green bay', 'A newer Bavaria with a wide stern and a big cockpit table. Handy for mooring practice in Fethiye bay and for a family charter afterwards.'),
  (9, 'dufour-390', 'Dufour 390', 2023, 12.0, 4.1, 2.0, 3, 6, 2, 40, 'Fethiye, Türkiye', 'Bareboat Skipper courses', 1990, '/fleet/dufour-390.webp', 'A Dufour 390 at anchor off a marina', 'Quick and well balanced, with the mainsheet led to the helm. A good boat for learning sail trim.'),
  (10, 'hanse-410', 'Hanse 410', 2024, 12.4, 4.2, 2.1, 3, 6, 2, 40, 'Göcek, Türkiye', 'Charter', 2620, '/fleet/hanse-410.webp', 'The cockpit and twin wheels of a Hanse 410', 'A self-tacking jib and every line led to the helm, so two people can sail her. Based in Göcek for charter between our courses.'),
  (11, 'jeanneau-sun-odyssey-410', 'Jeanneau Sun Odyssey 410', 2019, 12.3, 4.0, 2.1, 3, 8, 2, 45, 'Göcek, Türkiye', 'Training passages', 2350, '/fleet/jeanneau-sun-odyssey-410.webp', 'A Jeanneau Sun Odyssey 410 under sail at sunset', 'Walk-around side decks make it safe to move forward on a heeling boat, which is why we like her for passages and night watches.'),
  (12, 'hanse-460', 'Hanse 460', 2022, 14.3, 4.6, 2.3, 5, 10, 3, 60, 'Göcek, Türkiye', 'Passages and Yachtmaster', 3380, '/fleet/hanse-460.webp', 'The cockpit of a Hanse 460 moored in a marina', 'A big, stiff boat for open-sea legs and Yachtmaster weeks, with room for a crew of eight on long passages.'),
  (13, 'jeanneau-sun-odyssey-490', 'Jeanneau Sun Odyssey 490', 2022, 14.6, 4.5, 2.2, 5, 11, 3, 57, 'Göcek, Türkiye', 'Passages and Yachtmaster', 4390, '/fleet/jeanneau-sun-odyssey-490.webp', 'A Jeanneau Sun Odyssey 490 at anchor in a bay', 'Our largest monohull. Stable and comfortable on long legs, with five cabins for bigger crews and charter groups.'),
  (14, 'lagoon-40', 'Lagoon 40', 2021, 11.7, 6.9, 1.3, 6, 10, 4, 90, 'Fethiye, Türkiye', 'Charter', 3000, '/fleet/lagoon-40.webp', 'A Lagoon 40 catamaran moored in a marina', 'A catamaran for families and groups: level decks, a big saloon and twin engines that make harbour manoeuvres easy. We use it for charter and for catamaran handling practice.'),
  (15, 'lagoon-46', 'Lagoon 46', 2023, 14.0, 8.0, 1.4, 5, 9, 5, 114, 'Göcek, Türkiye', 'Charter', 4740, '/fleet/lagoon-46.webp', 'A Lagoon 46 catamaran moored stern-to', 'Spacious and stable, with a flybridge helm and a big cockpit. For charter groups who want comfort as well as good sailing.')
